/// <summary>
/// PricingAttribute of table <c>WHSInventFixedLocation</c> field ItemId.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeWHSInventFixedLocationItemId extends GUPPricingAttributeWHSInventFixedLocation implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(WHSInventFixedLocation, ItemId);
}

    public Set getAllowedValues()
    {
        var                    ret = new Set(Types::String);
        WHSInventFixedLocation wHSInventFixedLocation;

        while select wHSInventFixedLocation
            group by ItemId
        {
            if (! ret.in(wHSInventFixedLocation.ItemId))
            {
                ret.add(wHSInventFixedLocation.ItemId);
            }
        }

        return ret;
    }

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(WHSInventFixedLocation, ItemId));
        qbr.value(queryValue(_value));
    }
